-- 896: Internship landing page — add a "Good attitude" bullet to the
-- "What We Look For" list of all four internship tiers (ITE / Polytechnic /
-- University / Postgraduate), per a suggestion from the hiring side.
--
-- Rewrites the whole cms_block content in one shot (same approach as 871) so
-- the four inserted <li> rows are the ONLY delta — the replacement was built
-- from the live block content, so byte length grows by exactly 4 * 92 = 368.
--
-- Data-only, SG-only: targets cms_block by identifier, so partner sites
-- (MY/GH), which have no `internship_landing` block, are a silent no-op.
-- Idempotent: re-running rewrites the same content. Guarded on the bullet
-- being absent is unnecessary because the target content is absolute, not a
-- relative append.
--
-- Content is hex-encoded so apply.php's UTF-8 connection and its `;`
-- statement splitter never see raw HTML, quotes or semicolons.

UPDATE `cms_block`
   SET `content` = UNHEX('')
 WHERE `identifier` = 'internship_landing';
